// ============================================
// VALIDATION INPUT - Script Detector (Multi-mode)
// ============================================

const input = $input.first().json;
const body = input.body || input;
const ctx = body.context || {};

// --- Extract all possible inputs ---
const text = ctx.text || body.text;
const imageUrl = ctx.image_url || body.image_url;
const imageBase64 = ctx.image_base64 || body.image_base64;
const fileUrl = ctx.file_url || body.file_url;
const fileType = ctx.file_type || body.file_type;

// --- Extract API key ---
const openaiKey = body.openai_api_key 
  || ctx.openai_api_key 
  || body.plugin_context?.api_keys?.openai 
  || ctx.plugin_context?.api_keys?.openai;

// --- Determine mode ---
let mode = 'unknown';
let errors = [];

if (text && text.trim().length > 0) {
  mode = 'text';
} else if (imageUrl || imageBase64) {
  mode = 'image';
  if (!openaiKey) errors.push('openai_api_key requis pour les images');
} else if (fileUrl) {
  const ext = (fileUrl.split('.').pop() || '').toLowerCase().split('?')[0];
  if (ext === 'pdf') {
    mode = 'pdf';
    if (!openaiKey) errors.push('openai_api_key requis pour les PDFs');
  } else if (['jpg', 'jpeg', 'png', 'gif', 'webp', 'bmp'].includes(ext)) {
    mode = 'image';
    if (!openaiKey) errors.push('openai_api_key requis pour les images');
  } else {
    errors.push('Format fichier non supporté: ' + ext + '. Utilisez jpg, png, pdf, ou fournissez du texte.');
  }
} else {
  errors.push('Fournir text, image_url, image_base64, ou file_url');
}

if (errors.length > 0) {
  return { valid: false, errors: errors, mode: mode };
}

// --- Prepare image URL for Vision modes ---
let preparedImageUrl = '';
if (mode === 'image') {
  if (imageUrl) {
    preparedImageUrl = imageUrl;
  } else if (imageBase64) {
    // Detect MIME
    const prefix = imageBase64.substring(0, 20);
    let mime = 'image/png';
    if (prefix.startsWith('/9j/')) mime = 'image/jpeg';
    else if (prefix.startsWith('iVBOR')) mime = 'image/png';
    else if (prefix.startsWith('R0lG')) mime = 'image/gif';
    else if (prefix.startsWith('UklGR')) mime = 'image/webp';
    preparedImageUrl = 'data:' + mime + ';base64,' + imageBase64;
  }
} else if (mode === 'pdf') {
  // For PDF, we'll use the file URL directly - OpenAI Vision can handle PDFs
  preparedImageUrl = fileUrl;
}

return {
  valid: true,
  mode: mode,
  text: text || null,
  imageUrl: preparedImageUrl,
  fileUrl: fileUrl || null,
  openaiApiKey: openaiKey || null
};

// ============================================
// ANALYZE TEXT - Unicode Range Detection (GRATUIT)
// ============================================

const input = $input.first().json;
const text = input.text || '';

// Unicode ranges for script detection
const SCRIPT_RANGES = {
  hebrew: /[\u0590-\u05FF\uFB1D-\uFB4F]/g,
  arabic: /[\u0600-\u06FF\u0750-\u077F\u08A0-\u08FF\uFB50-\uFDFF\uFE70-\uFEFF]/g,
  latin: /[A-Za-z\u00C0-\u024F\u1E00-\u1EFF]/g,
  cyrillic: /[\u0400-\u04FF\u0500-\u052F]/g,
  greek: /[\u0370-\u03FF\u1F00-\u1FFF]/g,
  han: /[\u4E00-\u9FFF\u3400-\u4DBF\uF900-\uFAFF]/g,
  hiragana: /[\u3040-\u309F]/g,
  katakana: /[\u30A0-\u30FF]/g,
  hangul: /[\uAC00-\uD7AF\u1100-\u11FF\u3130-\u318F]/g,
  thai: /[\u0E00-\u0E7F]/g,
  devanagari: /[\u0900-\u097F]/g,
  tamil: /[\u0B80-\u0BFF]/g,
  telugu: /[\u0C00-\u0C7F]/g,
  bengali: /[\u0980-\u09FF]/g,
  gujarati: /[\u0A80-\u0AFF]/g,
  punjabi: /[\u0A00-\u0A7F]/g,
  malayalam: /[\u0D00-\u0D7F]/g,
  kannada: /[\u0C80-\u0CFF]/g,
  armenian: /[\u0530-\u058F]/g,
  georgian: /[\u10A0-\u10FF]/g,
  ethiopic: /[\u1200-\u137F]/g
};

// Diacritics detection
const DIACRITICS = {
  hebrew_nikud: /[\u05B0-\u05BD\u05BF\u05C1\u05C2\u05C4\u05C5\u05C7]/g,
  arabic_harakat: /[\u064B-\u0652\u0670]/g,
  latin_accents: /[\u0300-\u036F]/g
};

// Count characters per script
const counts = {};
let totalScriptChars = 0;

for (const [script, regex] of Object.entries(SCRIPT_RANGES)) {
  const matches = text.match(regex) || [];
  if (matches.length > 0) {
    counts[script] = matches.length;
    totalScriptChars += matches.length;
  }
}

// Build scripts array sorted by count
const scripts = Object.entries(counts)
  .map(([script, count]) => ({
    script: script,
    confidence: Math.min(0.95, 0.5 + (count / Math.max(totalScriptChars, 1)) * 0.5),
    percentage: Math.round((count / Math.max(totalScriptChars, 1)) * 100)
  }))
  .sort((a, b) => b.percentage - a.percentage);

const primaryScript = scripts.length > 0 ? scripts[0].script : 'unknown';

// RTL detection
const rtlScripts = ['hebrew', 'arabic', 'persian', 'urdu'];
const isRtl = rtlScripts.includes(primaryScript);

// Diacritics detection
let hasDiacritics = false;
if (primaryScript === 'hebrew') {
  hasDiacritics = DIACRITICS.hebrew_nikud.test(text);
} else if (primaryScript === 'arabic') {
  hasDiacritics = DIACRITICS.arabic_harakat.test(text);
} else if (primaryScript === 'latin') {
  hasDiacritics = DIACRITICS.latin_accents.test(text);
}

// Provider recommendations
const providerMap = {
  'hebrew': ['mistral', 'google_vision', 'tesseract'],
  'arabic': ['google_vision', 'azure', 'mistral'],
  'han': ['google_vision', 'azure', 'mistral'],
  'hiragana': ['google_vision', 'azure'],
  'katakana': ['google_vision', 'azure'],
  'hangul': ['google_vision', 'azure'],
  'devanagari': ['google_vision', 'azure'],
  'latin': ['mistral', 'google_vision', 'tesseract'],
  'cyrillic': ['google_vision', 'mistral', 'tesseract'],
  'greek': ['google_vision', 'mistral', 'tesseract']
};

const recommendedProviders = providerMap[primaryScript] || ['mistral', 'google_vision', 'tesseract'];

// Sample text
const sampleText = text.substring(0, 50) + (text.length > 50 ? '...' : '');

return {
  success: true,
  data: {
    primary_script: primaryScript,
    scripts: scripts.length > 0 ? scripts : [{ script: 'unknown', confidence: 0, percentage: 0 }],
    is_rtl: isRtl,
    has_diacritics: hasDiacritics,
    recommended_providers: recommendedProviders,
    sample_text: sampleText,
    char_count: totalScriptChars
  },
  meta: {
    mode: 'text',
    provider: 'unicode_analysis',
    cost: 0
  }
};

